using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;
using Neram.Unity;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;

namespace Neram.EditorTools
{
    /// <summary>
    /// Builds the theatre, patient, warming modules, wearable, controller, lights and camera presets from the data
    /// generated by tools/gen_neram_scene.py:
    ///   Assets/NERAM_Generated/MeshData/neram_scene.bytes   nodes + meshes (format documented in tools/meshgen/scene.py)
    ///   Assets/NERAM_Generated/MeshData/materials.json      URP material palette (single source of truth)
    ///   Assets/NERAM_Generated/Textures/*.png               labels, prop screens, floor, fabric
    /// Meshes are stored as sub-assets of Assets/NERAM_Generated/Meshes/NERAM_SceneMeshes.asset. Vertex data is used
    /// exactly as generated (Unity coordinates, outward winding), so left/right are never mirrored.
    /// Every failure here is reported as an error and returned to the caller (setup reports FAIL, never a warning).
    /// </summary>
    public static class NeramSceneBuilder
    {
        public const string BundlePath = "Assets/NERAM_Generated/MeshData/neram_scene.bytes";
        public const string MaterialsJsonPath = "Assets/NERAM_Generated/MeshData/materials.json";
        public const string TexturesDir = "Assets/NERAM_Generated/Textures";
        public const string MeshAssetPath = "Assets/NERAM_Generated/Meshes/NERAM_SceneMeshes.asset";

#pragma warning disable 0649 // fields are assigned by JsonUtility
        [Serializable] private sealed class MatSpec
        {
            public string name;
            public float[] color;
            public float smoothness;
            public float metallic;
            public float[] emission;
            public bool emissionKeyword;
            public string texture;
            public float tiling = 1f;
            public bool transparent;
            public float emissionFromTexture;
        }

        [Serializable] private sealed class MatList { public MatSpec[] materials; }
#pragma warning restore 0649

        private sealed class Node
        {
            public string name, parent, region, flags;
            public Vector3 pos;
            public Quaternion rot;
        }

        public sealed class Result
        {
            public readonly List<string> Errors = new List<string>();
            public readonly List<string> Info = new List<string>();
            public readonly Dictionary<string, Transform> Nodes = new Dictionary<string, Transform>();
            public readonly List<CameraPreset> Presets = new List<CameraPreset>();
            public Transform Assembly;
            public NeramAssemblyBinder Binder;
            public Transform ThermalAnchor;
            public Transform WearableAnchor;
            public Transform VesselRoot;
            public bool Ok => Errors.Count == 0;
        }

        // ------------------------------------------------------------------ textures + materials

        public static void ConfigureTextures(Result res)
        {
            if (!Directory.Exists(TexturesDir)) { res.Errors.Add("generated textures missing: " + TexturesDir + " (run tools/gen_neram_scene.py)"); return; }
            foreach (var file in Directory.GetFiles(TexturesDir, "*.png"))
            {
                var path = file.Replace('\\', '/');
                var imp = AssetImporter.GetAtPath(path) as TextureImporter;
                if (imp == null) continue;
                var stem = Path.GetFileNameWithoutExtension(path);
                bool tiled = stem == "floor_tiles" || stem == "fabric_weave";
                bool changed = imp.textureType != TextureImporterType.Default || imp.sRGBTexture != true || imp.mipmapEnabled != true ||
                               imp.wrapMode != (tiled ? TextureWrapMode.Repeat : TextureWrapMode.Clamp) || imp.anisoLevel != 8;
                if (!changed) continue;
                imp.textureType = TextureImporterType.Default;
                imp.sRGBTexture = true;
                imp.mipmapEnabled = true;
                imp.wrapMode = tiled ? TextureWrapMode.Repeat : TextureWrapMode.Clamp;
                imp.filterMode = FilterMode.Trilinear;
                imp.anisoLevel = 8;
                imp.SaveAndReimport();
            }
        }

        public static Dictionary<string, Material> EnsureMaterials(string materialsDir, Shader lit, Result res)
        {
            var mats = new Dictionary<string, Material>();
            var ta = AssetDatabase.LoadAssetAtPath<TextAsset>(MaterialsJsonPath);
            if (ta == null) { res.Errors.Add("material palette missing: " + MaterialsJsonPath + " (run tools/gen_neram_scene.py)"); return mats; }
            MatList list;
            try { list = JsonUtility.FromJson<MatList>(ta.text); }
            catch (Exception ex) { res.Errors.Add("materials.json does not parse: " + ex.Message); return mats; }
            if (list == null || list.materials == null || list.materials.Length == 0) { res.Errors.Add("materials.json contains no materials"); return mats; }
            Directory.CreateDirectory(materialsDir);
            foreach (var spec in list.materials)
            {
                var path = materialsDir + "/" + spec.name + ".mat";
                var m = AssetDatabase.LoadAssetAtPath<Material>(path);
                if (m == null)
                {
                    m = new Material(lit) { name = spec.name };
                    AssetDatabase.CreateAsset(m, path);
                }
                m.shader = lit;
                var c = spec.color != null && spec.color.Length >= 4 ? new Color(spec.color[0], spec.color[1], spec.color[2], spec.color[3]) : Color.white;
                if (m.HasProperty("_BaseColor")) m.SetColor("_BaseColor", c);
                if (m.HasProperty("_Color")) m.SetColor("_Color", c);
                if (m.HasProperty("_Smoothness")) m.SetFloat("_Smoothness", spec.smoothness);
                if (m.HasProperty("_Metallic")) m.SetFloat("_Metallic", spec.metallic);
                Texture2D tex = null;
                if (!string.IsNullOrEmpty(spec.texture))
                {
                    tex = AssetDatabase.LoadAssetAtPath<Texture2D>(TexturesDir + "/" + spec.texture + ".png");
                    if (tex == null) res.Errors.Add("material " + spec.name + ": texture " + spec.texture + ".png not found");
                }
                if (m.HasProperty("_BaseMap"))
                {
                    m.SetTexture("_BaseMap", tex);
                    m.SetTextureScale("_BaseMap", new Vector2(spec.tiling, spec.tiling));
                }
                if (spec.transparent) MakeTransparent(m); else MakeOpaque(m);
                var e = spec.emission != null && spec.emission.Length >= 3 ? new Color(spec.emission[0], spec.emission[1], spec.emission[2]) : Color.black;
                if (spec.emissionFromTexture > 0 && tex != null)
                {
                    m.EnableKeyword("_EMISSION");
                    if (m.HasProperty("_EmissionMap")) m.SetTexture("_EmissionMap", tex);
                    m.SetColor("_EmissionColor", Color.white * spec.emissionFromTexture);
                    m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;
                }
                else if (spec.emissionKeyword)
                {
                    // Runtime drives emission per renderer (MaterialPropertyBlock: replayed heating command, highlight).
                    // A tiny non-black base keeps URP from switching the keyword off when the material is re-validated.
                    m.EnableKeyword("_EMISSION");
                    if (m.HasProperty("_EmissionMap")) m.SetTexture("_EmissionMap", null);
                    var baseE = e.maxColorComponent > 0 ? e : new Color(0.001f, 0.001f, 0.001f);
                    m.SetColor("_EmissionColor", baseE);
                    m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;
                }
                else
                {
                    m.DisableKeyword("_EMISSION");
                    m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.EmissiveIsBlack;
                }
                EditorUtility.SetDirty(m);
                mats[spec.name] = m;
            }
            AssetDatabase.SaveAssets();
            res.Info.Add("materials: " + mats.Count + " from " + MaterialsJsonPath);
            return mats;
        }

        public static void MakeTransparent(Material m)
        {
            if (m.HasProperty("_Surface")) m.SetFloat("_Surface", 1f);
            if (m.HasProperty("_Blend")) m.SetFloat("_Blend", 0f);
            if (m.HasProperty("_SrcBlend")) m.SetFloat("_SrcBlend", (float)BlendMode.SrcAlpha);
            if (m.HasProperty("_DstBlend")) m.SetFloat("_DstBlend", (float)BlendMode.OneMinusSrcAlpha);
            if (m.HasProperty("_SrcBlendAlpha")) m.SetFloat("_SrcBlendAlpha", (float)BlendMode.One);
            if (m.HasProperty("_DstBlendAlpha")) m.SetFloat("_DstBlendAlpha", (float)BlendMode.OneMinusSrcAlpha);
            if (m.HasProperty("_ZWrite")) m.SetFloat("_ZWrite", 0f);
            m.SetShaderPassEnabled("ShadowCaster", false);
            m.SetShaderPassEnabled("DepthOnly", false);
            m.SetOverrideTag("RenderType", "Transparent");
            m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
            m.renderQueue = (int)RenderQueue.Transparent;
        }

        public static void MakeOpaque(Material m)
        {
            if (m.HasProperty("_Surface")) m.SetFloat("_Surface", 0f);
            if (m.HasProperty("_SrcBlend")) m.SetFloat("_SrcBlend", (float)BlendMode.One);
            if (m.HasProperty("_DstBlend")) m.SetFloat("_DstBlend", (float)BlendMode.Zero);
            if (m.HasProperty("_ZWrite")) m.SetFloat("_ZWrite", 1f);
            m.SetShaderPassEnabled("ShadowCaster", true);
            m.SetShaderPassEnabled("DepthOnly", true);
            m.SetOverrideTag("RenderType", "Opaque");
            m.DisableKeyword("_SURFACE_TYPE_TRANSPARENT");
            m.renderQueue = -1;
        }

        // ------------------------------------------------------------------ build

        private static Vector3 V3(float[] a, int i) => new Vector3(a[i], a[i + 1], a[i + 2]);

        /// <summary>Builds the generated scene content into the active scene. Returns errors/info in the result.</summary>
        public static Result Build(Dictionary<string, Material> mats)
        {
            var res = new Result();
            var ta = AssetDatabase.LoadAssetAtPath<TextAsset>(BundlePath);
            if (ta == null) { res.Errors.Add("scene bundle missing: " + BundlePath + " (run tools/gen_neram_scene.py)"); return res; }
            NeramBundleReader.Bundle bundle;
            try { bundle = NeramBundleReader.Read(ta.bytes); }
            catch (Exception ex)
            {
                res.Errors.Add("scene bundle could not be read: " + ex.Message);
                return res;
            }
            var nodes = new List<Node>();
            foreach (var nd in bundle.Nodes)
                nodes.Add(new Node
                {
                    name = nd.Name, parent = nd.Parent, region = nd.Region, flags = nd.Flags,
                    pos = V3(nd.Position, 0), rot = new Quaternion(nd.Rotation[0], nd.Rotation[1], nd.Rotation[2], nd.Rotation[3]),
                });
            var meshes = new List<(string name, string parent, string material, Mesh mesh, Vector3 pivot)>();
            foreach (var md in bundle.Meshes)
            {
                int nv = md.VertexCount;
                var v = new Vector3[nv];
                var nrm = new Vector3[nv];
                var uv = new Vector2[nv];
                for (int k = 0; k < nv; k++)
                {
                    v[k] = V3(md.Positions, k * 3);
                    nrm[k] = V3(md.Normals, k * 3);
                    uv[k] = new Vector2(md.Uvs[k * 2], md.Uvs[k * 2 + 1]);
                }
                var mesh = new Mesh { name = md.Name };
                if (nv > 65535) mesh.indexFormat = IndexFormat.UInt32;
                mesh.vertices = v;
                mesh.normals = nrm;
                mesh.uv = uv;
                mesh.triangles = md.Indices;
                mesh.RecalculateBounds();
                meshes.Add((md.Name, md.Parent, md.Material, mesh, V3(md.Pivot, 0)));
            }

            // Mesh assets: one container, rebuilt every time.
            Directory.CreateDirectory(Path.GetDirectoryName(MeshAssetPath) ?? "Assets/NERAM_Generated/Meshes");
            if (AssetDatabase.LoadAssetAtPath<UnityEngine.Object>(MeshAssetPath) != null) AssetDatabase.DeleteAsset(MeshAssetPath);
            var container = ScriptableObject.CreateInstance<NeramMeshContainer>();
            container.name = "NERAM_SceneMeshes";
            AssetDatabase.CreateAsset(container, MeshAssetPath);
            foreach (var m in meshes) AssetDatabase.AddObjectToAsset(m.mesh, container);
            AssetDatabase.SaveAssets();

            // Hierarchy
            foreach (var n in nodes)
            {
                var go = new GameObject(n.name);
                Transform parent = null;
                if (!string.IsNullOrEmpty(n.parent) && !res.Nodes.TryGetValue(n.parent, out parent))
                    res.Errors.Add("node " + n.name + ": parent " + n.parent + " not defined before it");
                go.transform.SetParent(parent, false);
                go.transform.position = n.pos;
                go.transform.rotation = n.rot;
                res.Nodes[n.name] = go.transform;
                ApplyNodeFlags(go, n, res, mats);
            }
            int tris = 0;
            foreach (var m in meshes)
            {
                if (!res.Nodes.TryGetValue(m.parent, out var parent)) { res.Errors.Add("mesh " + m.name + ": parent node " + m.parent + " missing"); continue; }
                var go = new GameObject(m.name);
                go.transform.SetParent(parent, false);
                go.transform.position = m.pivot;
                go.transform.rotation = Quaternion.identity;
                go.AddComponent<MeshFilter>().sharedMesh = m.mesh;
                var mr = go.AddComponent<MeshRenderer>();
                var matName = m.material.StartsWith("TEX:", StringComparison.Ordinal) ? "MAT_TEX_" + m.material.Substring(4) : m.material;
                if (!mats.TryGetValue(matName, out var mat)) { res.Errors.Add("mesh " + m.name + ": material " + matName + " not in palette"); }
                else mr.sharedMaterial = mat;
                bool thin = matName.StartsWith("MAT_TEX_", StringComparison.Ordinal) || matName == "MAT_GlassClear" || matName == "MAT_IVBag" || matName == "MAT_Hose";
                mr.shadowCastingMode = thin ? ShadowCastingMode.Off : ShadowCastingMode.On;
                if (go.GetComponentInParent<NeramRegion>() != null) go.AddComponent<MeshCollider>().sharedMesh = m.mesh;
                if (IsStatic(parent)) GameObjectUtility.SetStaticEditorFlags(go, StaticEditorFlags.BatchingStatic);
                tris += m.mesh.triangles.Length / 3;
            }
            // Cables are procedural tubes through their waypoints (CAD cables replace them by name).
            foreach (var n in nodes)
            {
                if (!HasFlag(n.flags, "cable")) continue;
                var go = res.Nodes[n.name].gameObject;
                var tube = go.AddComponent<CableTube>();
                tube.radius = 0.0042f;
                if (mats.TryGetValue("MAT_Cable", out var cm)) go.GetComponent<MeshRenderer>().sharedMaterial = cm;
                tube.Rebuild();
            }
            foreach (var r in UnityEngine.Object.FindObjectsByType<NeramRegion>(FindObjectsInactive.Include, FindObjectsSortMode.None)) r.Collect();
            res.Info.Add("scene bundle: " + nodes.Count + " nodes, " + meshes.Count + " meshes, " + tris.ToString("N0", CultureInfo.InvariantCulture) + " triangles");
            return res;
        }

        private static bool IsStatic(Transform t)
        {
            for (var p = t; p != null; p = p.parent)
            {
                var m = p.GetComponent<NeramStaticMarker>();
                if (m != null) return true;
            }
            return false;
        }

        private static bool HasFlag(string flags, string key)
        {
            foreach (var part in flags.Split(';')) if (part == key || part.StartsWith(key + ":", StringComparison.Ordinal)) return true;
            return false;
        }

        private static string FlagValue(string flags, string key)
        {
            foreach (var part in flags.Split(';')) if (part.StartsWith(key + ":", StringComparison.Ordinal)) return part.Substring(key.Length + 1);
            return null;
        }

        private static float F(string s) => float.Parse(s, CultureInfo.InvariantCulture);

        private static void ApplyNodeFlags(GameObject go, Node n, Result res, Dictionary<string, Material> mats)
        {
            var flags = n.flags ?? "";
            if (!string.IsNullOrEmpty(n.region))
            {
                var r = go.AddComponent<NeramRegion>();
                r.region = NeramRegion.Parse(n.region);
                r.channel = NeramRegion.ChannelOf(r.region);
                if (r.region == RegionId.None) res.Errors.Add("node " + n.name + ": unknown region key '" + n.region + "'");
            }
            var role = FlagValue(flags, "placeholder");
            if (role != null)
            {
                var pm = go.AddComponent<PlaceholderMarker>();
                pm.role = role;
                pm.note = "Generated visual stand-in (tools/gen_neram_scene.py). Not CAD and not a design dimension. A CAD object named '" + role +
                          "' under NERAM_Assembly replaces it automatically.";
            }
            if (HasFlag(flags, "static")) go.AddComponent<NeramStaticMarker>();
            if (HasFlag(flags, "assembly"))
            {
                res.Assembly = go.transform;
                res.Binder = go.AddComponent<NeramAssemblyBinder>();
                if (mats.TryGetValue("MAT_Halo", out var halo)) res.Binder.haloMaterial = halo;
            }
            if (n.name == SceneNames.ThermalAnchor) res.ThermalAnchor = go.transform;
            if (FlagValue(flags, "anchor") == "wearable") res.WearableAnchor = go.transform;
            if (HasFlag(flags, "vessels")) res.VesselRoot = go.transform;
            var vessel = FlagValue(flags, "vessel");
            if (vessel != null) go.AddComponent<NeramVessel>().kind = vessel;
            var kvs = new Dictionary<string, string>();
            foreach (var part in flags.Split(';'))
            {
                int eq = part.IndexOf('=');
                if (eq > 0) kvs[part.Substring(0, eq)] = part.Substring(eq + 1);
            }
            if (FlagValue(flags, "anchor") == "ivdrop")
            {
                var drip = go.AddComponent<IvDripAnimator>();
                if (kvs.TryGetValue("fall", out var fall)) drip.fallDistance = F(fall);
                if (mats.TryGetValue("MAT_IVDrop", out var dm)) drip.dropMaterial = dm;
            }
            var room = FlagValue(flags, "navroom");
            var keep = FlagValue(flags, "keepout");
            if (room != null || keep != null)
            {
                var h = (room ?? keep).Split(',');
                var nv = go.AddComponent<NeramNavVolume>();
                nv.halfExtents = new Vector3(F(h[0]), F(h[1]), F(h[2]));
                nv.isRoom = room != null;
            }
            var preset = FlagValue(flags, "preset");
            if (preset != null)
            {
                var p = preset.Split('|');
                var cp = go.AddComponent<CameraPreset>();
                cp.label = p[0];
                cp.yaw = F(p[1]);
                cp.pitch = F(p[2]);
                cp.distance = F(p[3]);
                cp.order = int.Parse(p[4], CultureInfo.InvariantCulture);
                res.Presets.Add(cp);
            }
            var light = FlagValue(flags, "light");
            if (light != null)
            {
                var l = go.AddComponent<Light>();
                var kv = new Dictionary<string, string>();
                foreach (var part in flags.Split(';'))
                {
                    int eq = part.IndexOf('=');
                    if (eq > 0) kv[part.Substring(0, eq)] = part.Substring(eq + 1);
                }
                l.type = light == "spot" ? LightType.Spot : light == "point" ? LightType.Point : LightType.Directional;
                if (kv.TryGetValue("intensity", out var it)) l.intensity = F(it);
                if (kv.TryGetValue("range", out var rg)) l.range = F(rg);
                if (kv.TryGetValue("angle", out var an)) l.spotAngle = F(an);
                if (kv.TryGetValue("inner", out var inn)) l.innerSpotAngle = F(inn);
                if (kv.TryGetValue("color", out var col))
                {
                    var c = col.Split(',');
                    l.color = new Color(F(c[0]), F(c[1]), F(c[2]));
                }
                l.shadows = kv.TryGetValue("shadows", out var sh) && sh == "soft" ? LightShadows.Soft : LightShadows.None;
            }
        }
    }
}
